import{_ as e,a as o,o as a,a4 as n}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Countries","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-countries","title":"List Countries","description":"Retrieve a paginated list of countries with their inline translations.","request":"curl -X GET \\"http://localhost/api/shop/countries?per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 255\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 128\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"code\\": \\"AF\\",\\n    \\"name\\": \\"Afghanistan\\",\\n    \\"states\\": [],\\n    \\"translations\\": [\\n      { \\"id\\": 1,   \\"countryId\\": 1, \\"locale\\": \\"ar\\",    \\"name\\": \\"أفغانستان\\" },\\n      { \\"id\\": 256, \\"countryId\\": 1, \\"locale\\": \\"es\\",    \\"name\\": \\"Afganistán\\" },\\n      { \\"id\\": 511, \\"countryId\\": 1, \\"locale\\": \\"fa\\",    \\"name\\": \\"افغانستان\\" },\\n      { \\"id\\": 766, \\"countryId\\": 1, \\"locale\\": \\"pt_BR\\", \\"name\\": \\"Afeganistão\\" }\\n    ]\\n  },\\n  {\\n    \\"id\\": 2,\\n    \\"code\\": \\"AX\\",\\n    \\"name\\": \\"Åland Islands\\",\\n    \\"states\\": [],\\n    \\"translations\\": [\\n      { \\"id\\": 2,   \\"countryId\\": 2, \\"locale\\": \\"ar\\", \\"name\\": \\"جزر آلاند\\" }\\n    ]\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]},{"id":"get-country","title":"Get Single Country","description":"Retrieve a single country by ID. States are inlined when the country has them.","request":"curl -X GET \\"http://localhost/api/shop/countries/40\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 40,\\n  \\"code\\": \\"CA\\",\\n  \\"name\\": \\"Canada\\",\\n  \\"states\\": [\\n    {\\n      \\"id\\": 66,\\n      \\"countryId\\": 40,\\n      \\"countryCode\\": \\"CA\\",\\n      \\"code\\": \\"AB\\",\\n      \\"defaultName\\": \\"Alberta\\",\\n      \\"translations\\": [\\n        \\"/api/shop/country_state_translations/66\\",\\n        \\"/api/shop/country_state_translations/634\\",\\n        \\"/api/shop/country_state_translations/1220\\",\\n        \\"/api/shop/country_state_translations/1788\\"\\n      ]\\n    },\\n    {\\n      \\"id\\": 67,\\n      \\"countryId\\": 40,\\n      \\"countryCode\\": \\"CA\\",\\n      \\"code\\": \\"BC\\",\\n      \\"defaultName\\": \\"British Columbia\\",\\n      \\"translations\\": [\\n        \\"/api/shop/country_state_translations/67\\",\\n        \\"/api/shop/country_state_translations/635\\",\\n        \\"/api/shop/country_state_translations/1221\\",\\n        \\"/api/shop/country_state_translations/1789\\"\\n      ]\\n    }\\n  ],\\n  \\"translations\\": [\\n    { \\"id\\": 40,  \\"countryId\\": 40, \\"locale\\": \\"ar\\", \\"name\\": \\"كندا\\" },\\n    { \\"id\\": 295, \\"countryId\\": 40, \\"locale\\": \\"es\\", \\"name\\": \\"Canadá\\" }\\n  ]\\n}\\n","commonErrors":[{"error":"404 Not Found","cause":"No country with the given `{id}` exists","solution":"List countries via `GET /api/shop/countries` to discover valid IDs."},{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."}]}]},"headers":[],"relativePath":"api/rest-api/shop/countries/get-countries.md","filePath":"api/rest-api/shop/countries/get-countries.md","lastUpdated":1783420618000}'),r={name:"api/rest-api/shop/countries/get-countries.md"};function s(i,t,d,c,l,h){return a(),o("div",null,t[0]||(t[0]=[n('<h1 id="countries" tabindex="-1">Countries <a class="header-anchor" href="#countries" aria-label="Permalink to &quot;Countries&quot;">​</a></h1><p>Countries are the catalog of nations available for billing/shipping addresses, taxes, and storefront scoping. Each country may have one or more sub-divisions (&quot;states&quot;, &quot;provinces&quot;, &quot;territories&quot; — generically called <em>country states</em> in this API).</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/countries</code></td><td>Paginated list of countries</td></tr><tr><td>GET</td><td><code>/api/shop/countries/{id}</code></td><td>Single country by ID</td></tr></tbody></table><p>Use the example switcher above to flip between the two.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Storefront API key (<code>pk_storefront_…</code>)</td></tr><tr><td><code>X-Locale</code></td><td>No</td><td>Override request locale</td></tr></tbody></table><h2 id="query-parameters-collection-only" tabindex="-1">Query Parameters (collection only) <a class="header-anchor" href="#query-parameters-collection-only" aria-label="Permalink to &quot;Query Parameters (collection only)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>1</td><td>Page number (1-based)</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>10</td><td>Items per page. Max <strong>50</strong>.</td></tr></tbody></table><p>Pagination headers (<code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, <code>X-Total-Pages</code>) are emitted on the collection. See <a href="/api/rest-api/introduction.html#pagination">Pagination</a>.</p><h2 id="country-object-fields" tabindex="-1">Country Object Fields <a class="header-anchor" href="#country-object-fields" aria-label="Permalink to &quot;Country Object Fields&quot;">​</a></h2><p>Both endpoints return the same shape — the collection wraps an array of these objects, the single endpoint returns one.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Country primary key</td></tr><tr><td><code>code</code></td><td>string</td><td>ISO 3166-1 alpha-2 country code (<code>AF</code>, <code>CA</code>, <code>US</code>, <code>IN</code>, …)</td></tr><tr><td><code>name</code></td><td>string</td><td>Default English name</td></tr><tr><td><code>states</code></td><td>array</td><td>Inline list of <a href="/api/rest-api/shop/countries/get-country-states.html">country states</a> for this country. Empty <code>[]</code> for countries with no sub-divisions in Bagisto&#39;s data</td></tr><tr><td><code>translations</code></td><td>array</td><td>All locale translations as <strong>inline objects</strong>: <code>{ id, countryId, locale, name }</code></td></tr></tbody></table><blockquote><p>⚠️ Unlike <code>Attribute</code> / <code>Channel</code> / <code>Category</code>, <code>translations</code> on Country is returned as <strong>inline objects</strong> (not IRI strings). This avoids an extra round-trip per locale. There is no <code>translation</code> field for the request locale — pick the entry that matches your <code>X-Locale</code>.</p></blockquote><h3 id="inline-states-shape" tabindex="-1">Inline <code>states[]</code> shape <a class="header-anchor" href="#inline-states-shape" aria-label="Permalink to &quot;Inline `states[]` shape&quot;">​</a></h3><p>Each entry has the same fields as <code>/country-states/{id}</code> — see the <a href="/api/rest-api/shop/countries/get-country-states.html">Country States</a> page.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li>Populate a country dropdown in a checkout / address form.</li><li>Look up a country by ISO code (<code>?code=US</code>) is <strong>not</strong> supported — fetch the full list and filter client-side, or use the GraphQL query for a single lookup.</li><li>Resolve a country&#39;s localized display name from <code>translations[]</code> based on the customer&#39;s locale.</li><li>Chain to the country&#39;s states for a country/state cascade picker (use the <a href="/api/rest-api/shop/countries/get-country-states.html">nested states endpoint</a> to skip refetching the country payload).</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/countries/get-country-states.html">Country States</a></li><li><a href="/api/rest-api/introduction.html#iris-hateoas">Introduction → IRIs &amp; HATEOAS</a></li></ul>',20)]))}const y=e(r,[["render",s]]);export{p as __pageData,y as default};
